const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'G' },
      { kind: 'text', payload: 'N' },
      { kind: 'text', payload: 'f' },
      { kind: 'text', payload: '30°' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var DEG = Math.PI / 180;
    var ang = 30 * DEG;
    var margin = Math.max(36, w * 0.08);
    var yBase = h - 64;
    var maxL = Math.min(w - 2 * margin, (yBase - 72) / Math.sin(ang));
    var L = Math.max(140, Math.min(320, maxL));
    var A = { x: margin, y: yBase };
    var B = { x: A.x + L * Math.cos(ang), y: yBase };
    var C = { x: B.x, y: yBase - L * Math.sin(ang) };

    var u = { x: Math.cos(ang), y: -Math.sin(ang) };
    var n = { x: -Math.sin(ang), y: -Math.cos(ang) };
    var t = 0.54;
    var S = { x: A.x + t * (C.x - A.x), y: A.y + t * (C.y - A.y) };
    var bw = 48;
    var bh = 30;
    var bl = { x: S.x - bw / 2 * u.x, y: S.y - bw / 2 * u.y };
    var br = { x: S.x + bw / 2 * u.x, y: S.y + bw / 2 * u.y };
    var tl = { x: bl.x + bh * n.x, y: bl.y + bh * n.y };
    var tr = { x: br.x + bh * n.x, y: br.y + bh * n.y };
    var center = { x: S.x + bh / 2 * n.x, y: S.y + bh / 2 * n.y };

    var triangle = ['M', A.x, A.y, 'L', B.x, B.y, 'L', C.x, C.y, 'Z'];
    var block = ['M', bl.x, bl.y, 'L', br.x, br.y, 'L', tr.x, tr.y, 'L', tl.x, tl.y, 'Z'];

    var gLen = 92;
    var nLen = 84;
    var fLen = 74;
    var gTip = { x: center.x, y: center.y + gLen };
    var nTip = { x: center.x + n.x * nLen, y: center.y + n.y * nLen };
    var fTip = { x: center.x + u.x * fLen, y: center.y + u.y * fLen };

    var gArrow = visualSdk.arrow(center.x, center.y, gTip.x, gTip.y, {});
    var nArrow = visualSdk.arrow(center.x, center.y, nTip.x, nTip.y, {});
    var fArrow = visualSdk.arrow(center.x, center.y, fTip.x, fTip.y, {});

    var arcR = 40;
    var angleArc = visualSdk.arc(A.x, A.y, arcR, -ang, 0);

    function dim(i, fw, fh) {
      var m = metrics && metrics[i];
      var tw = m && (m.width || m.w) ? (m.width || m.w) : fw;
      var th = m && (m.height || m.h) ? (m.height || m.h) : fh;
      return { w: tw, h: th };
    }
    var gm = dim(0, 14, 18);
    var nm = dim(1, 14, 18);
    var fm = dim(2, 10, 18);
    var am = dim(3, 30, 18);

    var gLabelPos = { x: gTip.x + gm.w / 2 + 8, y: gTip.y };
    var nLabelPos = { x: nTip.x + n.x * (nm.w / 2 + 10), y: nTip.y + n.y * (nm.h / 2 + 10) };
    var fLabelPos = { x: fTip.x + u.x * (fm.w / 2 + 12) + n.x * 10, y: fTip.y + u.y * (fm.h / 2 + 12) + n.y * 10 };
    var bis = -ang / 2;
    var aLabelPos = { x: A.x + (arcR + 22) * Math.cos(bis), y: A.y + (arcR + 22) * Math.sin(bis) };

    var root = {
      type: 'group',
      children: [
        { type: 'path', pathId: 'triangle', stroke: '#26354a', fill: '#eef3f9' },
        { type: 'path', pathId: 'block', stroke: '#26354a', fill: '#f7f9fc' },
        { type: 'path', pathId: 'angleArc', stroke: '#26354a' },
        { type: 'path', pathId: 'gArrow', stroke: '#b00020' },
        { type: 'path', pathId: 'nArrow', stroke: '#1565c0' },
        { type: 'path', pathId: 'fArrow', stroke: '#2e7d32' },
        { type: 'label', text: 'G', x: gLabelPos.x, y: gLabelPos.y, fontSize: 16, fill: '#b00020', align: 'center', baseline: 'middle' },
        { type: 'label', text: 'N', x: nLabelPos.x, y: nLabelPos.y, fontSize: 16, fill: '#1565c0', align: 'center', baseline: 'middle' },
        { type: 'label', text: 'f', x: fLabelPos.x, y: fLabelPos.y, fontSize: 16, fill: '#2e7d32', align: 'center', baseline: 'middle' },
        { type: 'label', text: '30°', x: aLabelPos.x, y: aLabelPos.y, fontSize: 15, fill: '#26354a', align: 'center', baseline: 'middle' }
      ]
    };

    return {
      schemaVersion: 1,
      sceneId: 'inclined-plane-forces',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'triangle', commands: triangle },
        { id: 'block', commands: block },
        { id: 'angleArc', commands: angleArc },
        { id: 'gArrow', commands: gArrow },
        { id: 'nArrow', commands: nArrow },
        { id: 'fArrow', commands: fArrow }
      ],
      root: root
    };
  }
};
